const ROLES={"owner": "مالک محصول", "head_owner": "مدیر مالکین محصول", "tech_manager": "مدیر فنی", "tech": "کارشناس فنی", "commercial_manager": "مدیر بازرگانی", "commercial": "کارشناس بازرگانی", "admin": "مدیر سامانه"};
const PERMISSIONS={owner:['projects','tasks','approval'],head_owner:['projects','tasks','approval','portfolio','assign_owner','transfer_owner','create_project','escalation','reports'],tech_manager:['items','assemblies','tasks','technical'],tech:['items','assemblies','tasks'],commercial_manager:['quotations','suppliers','tasks','commercial'],commercial:['quotations','suppliers','tasks'],admin:['users','tasks']};
