const statusFa={Draft:'پیش‌نویس',Estimate:'برآورد',Approved:'مصوب',Contracted:'قراردادی',Archived:'بایگانی'};
function relatedProjects(state,entityId){const defs=[...(state.assemblies||[]),...(state.projects||[])];const byId=id=>defs.find(x=>x.id===id);const seen=new Set();function contains(id,depth=0){if(id===entityId)return true;if(depth>30||seen.has(id))return false;seen.add(id);return(byId(id)?.lines||[]).some(l=>l.kind==='assembly'&&contains(l.ref,depth+1))}return(state.projects||[]).filter(p=>{seen.clear();return contains(p.id)}).map(p=>p.id)}
function collectChanges(oldState,newState){const out=[];for(const collection of ['projects','assemblies','items','suppliers','quotations','tasks']){const before=new Map((oldState[collection]||[]).map(x=>[x.id,x]));const after=new Map((newState[collection]||[]).map(x=>[x.id,x]));for(const id of new Set([...before.keys(),...after.keys()])){const a=before.get(id),b=after.get(id);if(!a||!b){out.push({collection,entityId:id,action:a?'حذف':'ایجاد',field:'record',before:a||null,after:b||null});continue}const keys=new Set([...Object.keys(a),...Object.keys(b)]);for(const key of keys){if(key==='audit')continue;if(key==='lines'){const oldLines=new Map((a.lines||[]).map(l=>[l.id,l]));const newLines=new Map((b.lines||[]).map(l=>[l.id,l]));for(const lineId of new Set([...oldLines.keys(),...newLines.keys()])){const x=oldLines.get(lineId),y=newLines.get(lineId);if(JSON.stringify(x)!==JSON.stringify(y))out.push({collection,entityId:id,action:!x?'افزودن جزء':!y?'حذف جزء':'ویرایش جزء',field:'lines/'+lineId,before:x||null,after:y||null})}continue}if(key==='baselines'){if((b.baselines||[]).length!==(a.baselines||[]).length)out.push({collection,entityId:id,action:'ثبت Baseline',field:'baselines',before:(a.baselines||[]).map(x=>x.id),after:(b.baselines||[]).map(x=>x.id)});continue}if(key==='estimateHistory')continue;if(key==='overrides'){const all=new Set([...Object.keys(a.overrides||{}),...Object.keys(b.overrides||{})]);for(const path of all)if(a.overrides?.[path]!==b.overrides?.[path])out.push({collection,entityId:id,action:'تغییر قیمت انتخابی',field:'overrides/'+path,before:a.overrides?.[path]||null,after:b.overrides?.[path]||null});continue}if(JSON.stringify(a[key])!==JSON.stringify(b[key]))out.push({collection,entityId:id,action:key==='status'?'تغییر وضعیت':key==='revision'?'تغییر نسخه':'ویرایش',field:key,before:a[key]??null,after:b[key]??null})}}}return out}

const money=n=>Number(n||0).toLocaleString('fa-IR');
const clean=val=>String(val||'').toLowerCase();
const uid=(prefix)=>`${prefix}-${Date.now().toString(36).toUpperCase().slice(-6)}${Math.random().toString(36).slice(2,5).toUpperCase()}`;
const clone=v=>JSON.parse(JSON.stringify(v));
function App(){
 const [data,setData]=useState(null),[tab,setTab]=useState('dashboard'),[selectedProject,setSelectedProject]=useState('PRJ-001'),[expanded,setExpanded]=useState({}),[chosen,setChosen]=useState([]),[search,setSearch]=useState(''),[notice,setNotice]=useState(''),[mobileMenu,setMobileMenu]=useState(false),[actor,setActor]=useState(localStorage.getItem('bom-demo-actor')||'کاربر دمو'),[historyProject,setHistoryProject]=useState(''),[activeRole,setActiveRole]=useState(localStorage.getItem('bom-demo-role')||'owner'),[taskFilter,setTaskFilter]=useState('mine'),[profile,setProfile]=useState(null);
 useEffect(()=>{(async()=>{try{const loaded={};for(const k of DATA){const r=await fetch(`${import.meta.env.BASE_URL}data/${k}.json`);if(!r.ok)throw Error(k);loaded[k]=await r.json()}const local=localStorage.getItem(KEY);setData({...loaded,...(local?JSON.parse(local):{}),tasks:local?JSON.parse(local).tasks||loaded.tasks:loaded.tasks})}catch(e){setNotice('خطا در بارگذاری داده‌ها: '+e.message)}})()},[]);
 const persist=(fn)=>setData(prev=>{const next=clone(prev);fn(next);const differences=collectChanges(prev,next);next.audit=Array.isArray(next.audit)?next.audit:[];const now=new Date().toISOString();for(const c of differences){let affected=[];if(c.collection==='projects')affected=[c.entityId];else if(c.collection==='assemblies'){affected=[...new Set([...relatedProjects(prev,c.entityId),...relatedProjects(next,c.entityId)])]}else if(c.collection==='quotations'){const itm=(next.quotations||[]).find(q=>q.id===c.entityId)?.itemId;affected=(next.projects||[]).filter(p=>JSON.stringify(p.lines).includes(itm||'__none__')).map(p=>p.id)}else if(c.collection==='tasks'){affected=[c.after?.projectId||c.before?.projectId].filter(Boolean)}else if(c.collection==='items'){affected=(next.projects||[]).filter(p=>JSON.stringify(p.lines).includes(c.entityId)).map(p=>p.id)}next.audit.push({id:uid('EVT'),timestamp:now,actor:actor.trim()||'کاربر دمو',actorRole:activeRole,...c,projectIds:affected})}try{localStorage.setItem(KEY,JSON.stringify(next))}catch{}return next});
 const affectedBy=id=>relatedProjects(data||{assemblies:[],projects:[]},id);
 const protectedProjects=ids=>ids.map(id=>projects.find(p=>p.id===id)).filter(p=>p&&!EDITABLE.includes(p.status));
 const canEdit=(targetId)=>{if(activeRole==='owner'&&affectedBy(targetId).some(id=>{const p=projects.find(x=>x.id===id);return p?.ownerName!==actor.trim()})){toast('این پروژه به مالک محصول فعال تخصیص داده نشده است.');return false}if(activeRole==='head_owner'&&affectedBy(targetId).some(id=>!inManagerScope(projects.find(p=>p.id===id)))){toast('این ساختار به پروژه خارج از حوزه مدیریتی شما متصل است.');return false}const blocked=protectedProjects(affectedBy(targetId));if(blocked.length){toast('ابتدا برای پروژه مصوب، نسخه کاری جدید بسازید: '+blocked.map(p=>p.name).join('، '));return false}return true};
 const tasks=data?.tasks||[]; const canRole=(permission)=>!!PERMISSIONS[activeRole]?.includes(permission);
 const inManagerScope=p=>activeRole!=='head_owner'||!p||p.managerName===(actor.trim()||'کاربر دمو');
 const managedProjects=projectsForManager=>projectsForManager.filter(p=>p.managerName===(actor.trim()||'کاربر دمو'));
 function assignOwner(projectId,newOwner){if(activeRole!=='head_owner')return toast('این عملیات مخصوص مدیر مالکین محصول است.');const pr=projects.find(p=>p.id===projectId);if(!pr)return;if(pr.managerName&&pr.managerName!==actor.trim())return toast('این پروژه در حوزه مدیر دیگری قرار دارد.');const name=newOwner.trim();if(!name)return toast('نام مالک محصول الزامی است.');if(name===actor.trim())return toast('مالک مسئول باید از مدیر تخصیص‌دهنده متفاوت باشد.');persist(d=>{const p=d.projects.find(x=>x.id===projectId);p.ownerName=name;p.managerName=actor.trim()||'کاربر دمو'});toast('مسئولیت پروژه ثبت شد و در تاریخچه قابل پیگیری است.')}

 const items=data?.items||[], assemblies=data?.assemblies||[], projects=data?.projects||[],quotes=data?.quotations||[],suppliers=data?.suppliers||[];
 const project=projects.find(p=>p.id===selectedProject)||projects[0];
 const projectEditable=!!project&&EDITABLE.includes(project.status)&&(activeRole!=='owner'||project.ownerName===actor.trim())&&(activeRole!=='head_owner'||inManagerScope(project));
 const canEditReadonly=id=>!protectedProjects(affectedBy(id)).length&&(activeRole!=='head_owner'||affectedBy(id).every(pid=>inManagerScope(projects.find(p=>p.id===pid))));
 const defById=id=>[...assemblies,...projects].find(x=>x.id===id);
 const quoteById=id=>quotes.find(x=>x.id===id);
 // Paths identify occurrences, not catalog item IDs. The same item can have a distinct selected price in every occurrence.
 function buildNodes(entity,context='',trail=[],depth=0){if(depth>25||trail.includes(entity.id))return [];return(entity.lines||[]).map(l=>{const path=context?`${context}/${l.id}`:l.id;const def=l.kind==='assembly'?defById(l.ref):items.find(x=>x.id===l.ref);const children=l.kind==='assembly'&&def?buildNodes(def,path,[...trail,entity.id],depth+1):[];return{...l,path,parentId:entity.id,def,children};})}
 const tree=useMemo(()=>project?buildNodes(project,'',[ ],0):[],[data,selectedProject]);
 const walk=(nodes,fn)=>nodes.forEach(n=>{fn(n);walk(n.children,fn)});
 const allLeaves=[];walk(tree,n=>{if(n.kind==='item')allLeaves.push(n)});
 const activeQ=(leaf)=>quoteById(project?.overrides?.[leaf.path]||leaf.quotationId);
 const latestQuote=(itemId)=>quotes.filter(q=>q.itemId===itemId).sort((a,b)=>b.date.localeCompare(a.date))[0];
 const pricedQ=(leaf,preview=false)=>quoteById(preview&&chosen.includes(leaf.path)?latestQuote(leaf.ref)?.id:(project?.overrides?.[leaf.path]||leaf.quotationId));
 const eligible=(leaf)=>{const next=latestQuote(leaf.ref),cur=activeQ(leaf);return next&&cur&&next.price!==cur.price&&next.currency===cur.currency&&next.id!==cur.id};
 const changed=allLeaves.filter(eligible);
 function total(nodes,mult=1,preview=false){return nodes.reduce((sum,n)=>{const q=mult*Number(n.qty||0);return sum+(n.kind==='item'?q*Number(pricedQ(n,preview)?.price||0):total(n.children,q,preview))},0)}
 const totalNow=total(tree),totalPreview=total(tree,1,true);
 const leavesOf=node=>{const l=[];walk([node],n=>{if(n.kind==='item')l.push(n)});return l};
 function toggleSelect(paths,on){setChosen(v=>on?[...new Set([...v,...paths])]:v.filter(p=>!paths.includes(p)))}
 const toast=m=>{setNotice(m);setTimeout(()=>setNotice(''),4500)};
 function addItem(e){if(!canRole('items'))return toast('نقش انتخابی مجوز ثبت قلم ندارد.');e.preventDefault();const f=new FormData(e.currentTarget);const mpn=String(f.get('mpn')).trim(),manufacturer=String(f.get('manufacturer')).trim();if(items.some(i=>clean(i.mpn)===clean(mpn)&&clean(i.manufacturer)===clean(manufacturer)))return toast('این سازنده و Part Number قبلاً ثبت شده‌اند.');const id=uid('ITM');persist(d=>d.items.push({id,name:f.get('name'),mpn,manufacturer,category:f.get('category')||'Other',unit:'عدد',attributes:{}}));e.currentTarget.reset();toast('قلم '+id+' ثبت شد.')}
 function addSupplier(e){if(!canRole('suppliers'))return toast('مجوز مدیریت تأمین‌کننده ندارید.');e.preventDefault();const f=new FormData(e.currentTarget);persist(d=>d.suppliers.push({id:uid('SUP'),name:f.get('name'),contact:f.get('contact'),city:f.get('city')}));e.currentTarget.reset();toast('تأمین‌کننده ثبت شد.')}
 function addQuotation(e){if(!canRole('quotations'))return toast('مجوز ثبت استعلام ندارید.');e.preventDefault();const f=new FormData(e.currentTarget);persist(d=>d.quotations.push({id:uid('Q'),itemId:f.get('itemId'),supplierId:f.get('supplierId'),price:Number(f.get('price')),currency:'تومان',date:f.get('date'),validUntil:f.get('validUntil'),minQty:Number(f.get('minQty')||1)}));e.currentTarget.reset();toast('استعلام ثبت شد.')}
 function addAssembly(e){if(!canRole('assemblies'))return toast('مجوز تعریف ماژول ندارید.');e.preventDefault();const f=new FormData(e.currentTarget);const type=f.get('type');const id=uid(type==='module'?'MOD':'SYS');persist(d=>d.assemblies.push({id,type,name:f.get('name'),revision:'A',lines:[]}));e.currentTarget.reset();toast('ساختار '+id+' ایجاد شد.')}
 function addProject(e){e.preventDefault();if(activeRole!=='head_owner')return toast('فقط مدیر مالکین محصول مجاز به ایجاد پروژه است.');const f=new FormData(e.currentTarget);const ownerName=String(f.get('ownerName')||'').trim();const managerName=actor.trim();if(!managerName||managerName==='کاربر دمو')return toast('ابتدا نام مدیر ایجادکننده را در سربرگ مشخص کنید.');if(!ownerName)return toast('تعیین مالک محصول مسئول الزامی است.');if(ownerName===managerName)return toast('مالک محصول مسئول باید شخصی غیر از مدیر ایجادکننده باشد.');const name=String(f.get('name')||'').trim();if(!name)return toast('عنوان پروژه الزامی است.');const id=uid('PRJ');persist(d=>{d.projects.push({id,type:'project',name,status:'Draft',revision:'00',ownerName,managerName,description:String(f.get('description')||''),priority:String(f.get('priority')||'متوسط'),createdAt:new Date().toISOString(),lines:[],overrides:{},baselines:[]});d.tasks||=[];d.tasks.push({id:uid('TASK'),title:'آغاز و تکمیل اطلاعات پروژه '+name,projectId:id,assigneeRole:'owner',assigneeName:ownerName,owner:managerName,priority:'بالا',deadline:'',status:'open',approvalStep:null});for(const [step,assigneeRole,title] of [['technical','tech_manager','تأیید فنی BOM'],['commercial','commercial_manager','تأیید تجاری قیمت‌ها']])d.tasks.push({id:uid('TASK'),title,projectId:id,assigneeRole,owner:managerName,priority:'بالا',deadline:'',status:'open',approvalStep:step});});setSelectedProject(id);e.currentTarget.reset();toast('پروژه در وضعیت پیش‌نویس ایجاد و به مالک محصول اختصاص یافت.')}
 function addLine(e){if(!canRole('assemblies')&&!canRole('projects'))return toast('نقش فعال اجازه تغییر BOM ندارد.');e.preventDefault();const f=new FormData(e.currentTarget);const target=f.get('target');if(!canEdit(target))return;const targetDef=defById(target);const ref=f.get('ref'), kind=f.get('kind');if(!targetDef)return;const child=defById(ref);if(kind==='assembly'&&(!child||ref===target))return toast('انتخاب نامعتبر است.');const typeParent=targetDef.type, typeChild=kind==='item'?'item':child.type;const allowed={module:['item','module'],system:['item','module','system'],project:['item','module','system','project']};if(!allowed[typeParent]?.includes(typeChild))return toast('این نوع جزء برای ساختار انتخاب‌شده مجاز نیست.');function hasCycle(start,needle,visited=new Set()){if(start===needle)return true;if(visited.has(start))return false;visited.add(start);return (defById(start)?.lines||[]).some(l=>l.kind==='assembly'&&hasCycle(l.ref,needle,visited))}if(kind==='assembly'&&hasCycle(ref,target))return toast('این رابطه باعث ایجاد حلقه می‌شود.');let finalRef=ref; if(kind==='assembly'&&f.get('mode')==='duplicate'){const newDef=clone(child);newDef.id=uid(child.type==='project'?'PRJ':child.type==='system'?'SYS':'MOD');newDef.name=child.name+' (نسخه سفارشی)';newDef.sourceId=child.id;newDef.lines=newDef.lines.map(x=>({...x,id:uid('LN')}));if(child.type==='project'){newDef.overrides={};newDef.baselines=[]}persist(d=>{(child.type==='project'?d.projects:d.assemblies).push(newDef)});finalRef=newDef.id;} const line={id:uid('LN'),kind,ref:finalRef,qty:Math.max(0.001,Number(f.get('qty')||1)),...(kind==='item'?{quotationId:latestQuote(ref)?.id||null}:{mode:f.get('mode')})};persist(d=>{const arr=[...d.assemblies,...d.projects];const a=arr.find(x=>x.id===target);a.lines.push(line)});e.currentTarget.reset();toast('جزء به ساختار اضافه شد.')}
 function duplicateAssembly(id){const src=defById(id);if(!src)return;const next=clone(src);next.id=uid(src.type==='system'?'SYS':src.type==='project'?'PRJ':'MOD');next.name=src.name+' (کپی سفارشی)';next.sourceId=src.id;next.revision='A';next.lines=next.lines.map(l=>({...l,id:uid('LN')}));if(next.type==='project'){next.overrides={};next.baselines=[];persist(d=>d.projects.push(next))}else persist(d=>d.assemblies.push(next));toast('کپی مستقل '+next.id+' ساخته شد. برای استفاده، آن را به ساختار موردنظر اضافه کنید.')}
 function applyPrices(){if(!canRole('commercial_manager')&&!canRole('commercial')&&!canRole('projects'))return toast('مجوز قیمت‌گذاری ندارید.');if(!projectEditable)return toast('این پروژه قفل است؛ نسخه کاری جدید بسازید.');if(activeRole==='head_owner'&&!inManagerScope(project))return toast('پروژه خارج از حوزه شماست.');if(!chosen.length)return;const selected=changed.filter(l=>chosen.includes(l.path));if(!selected.length)return;persist(d=>{const p=d.projects.find(x=>x.id===project.id);p.overrides||={};for(const n of selected)p.overrides[n.path]=latestQuote(n.ref).id;p.estimateHistory||=[];p.estimateHistory.push({id:uid('EST'),at:new Date().toISOString(),updates:selected.map(n=>({path:n.path,from:activeQ(n)?.id,to:latestQuote(n.ref)?.id}))})});setChosen([]);toast(`${selected.length} قیمت در برآورد کاری اعمال شد؛ نسخه‌های مصوب تغییر نکردند.`)}
 function updateQty(parentId,lineId,value){if(!canRole('assemblies')&&!canRole('projects'))return toast('مجوز تغییر تعداد ندارید.');if(!canEdit(parentId))return;const qty=Number(value);if(!Number.isFinite(qty)||qty<=0)return toast('تعداد باید عددی بزرگ‌تر از صفر باشد.');const parent=defById(parentId);const line=parent?.lines?.find(l=>l.id===lineId);if(!line)return toast('ردیف BOM یافت نشد.');if(Number(line.qty)===qty)return;persist(d=>{const target=[...d.projects,...d.assemblies].find(x=>x.id===parentId);const entry=target?.lines.find(l=>l.id===lineId);if(entry)entry.qty=qty});setChosen([]);toast('تعداد به‌روزرسانی شد و هزینه‌ها دوباره محاسبه شدند.')}
 function removeLine(parentId,lineId){if(!canRole('assemblies')&&!canRole('projects'))return toast('مجوز حذف جزء ندارید.');if(!canEdit(parentId))return;const parent=defById(parentId),line=parent?.lines?.find(l=>l.id===lineId);if(!line)return;if(!confirm('این ردیف و تمام اجزای زیرمجموعه آن از ساختار حذف شوند؟ تغییر در تاریخچه ثبت می‌شود.'))return;persist(d=>{const target=[...d.assemblies,...d.projects].find(x=>x.id===parentId);target.lines=target.lines.filter(l=>l.id!==lineId)});setChosen([]);toast('ردیف BOM حذف شد و سابقه آن ثبت شد.')}
 function qtyOnPath(path){return path.split('/').reduce((qty,id,index,parts)=>{const prefix=parts.slice(0,index+1).join('/');let hit;walk(tree,n=>{if(n.path===prefix)hit=n});return qty*Number(hit?.qty||1)},1)}
 function baseline(){if(!project||!projectEditable)return toast('ثبت Baseline فقط در نسخه کاری مجاز است.');const snapshot={id:uid('BASE'),createdAt:new Date().toISOString(),root:clone(project.lines),definitions:clone(assemblies),items:clone(items),priceLines:allLeaves.map(n=>({path:n.path,itemId:n.ref,qty:n.qty,effectiveQty:qtyOnPath(n.path),quotation:clone(activeQ(n))})),total:totalNow};persist(d=>{let p=d.projects.find(x=>x.id===project.id);p.baselines||=[];p.baselines.push(snapshot)});toast('Snapshot مستقل و غیرقابل ویرایش ثبت شد.')}
 function downloadJson(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='bom-app-backup.json';a.click();URL.revokeObjectURL(url)}
 function importJson(file){if(!file)return;file.text().then(t=>{try{const obj=JSON.parse(t);if(!DATA.every(k=>Array.isArray(obj[k])))throw Error('ساختار فایل نامعتبر است');obj.audit=Array.isArray(obj.audit)?obj.audit:[];obj.audit.push({id:uid('EVT'),timestamp:new Date().toISOString(),actor:actor||'کاربر دمو',action:'بازیابی فایل JSON',collection:'system',entityId:'IMPORT',field:'import',before:null,after:'فایل پشتیبان بازیابی شد',projectIds:obj.projects.map(p=>p.id)});setData(obj);localStorage.setItem(KEY,JSON.stringify(obj));setChosen([]);toast('بازیابی JSON انجام شد.')}catch(e){toast('خطای فایل: '+e.message)}})}
 function reset(){if(!confirm('تمام تغییرات ذخیره‌شده در این مرورگر پاک شود؟'))return;localStorage.removeItem(KEY);location.reload()}
 function transitionStatus(nextStatus){if(!projectEditable&&EDITABLE.includes(project?.status))return toast('فقط مالک مسئول یا مدیر حوزه مجاز به تغییر این پروژه است.');if(activeRole==='owner'&&project?.ownerName!==actor.trim())return toast('پروژه به شما تخصیص نیافته است.');if(activeRole==='head_owner'&&!inManagerScope(project))return toast('پروژه خارج از حوزه مدیریتی است.');if(!canRole('approval'))return toast('این نقش مجوز تصویب نهایی ندارد.');if(activeRole==='head_owner'&&!inManagerScope(project))return toast('پروژه خارج از حوزه مدیریتی شماست؛ ابتدا مدیر مسئول پروژه را تعیین کنید.');if(nextStatus==='Approved'&&!['technical','commercial'].every(step=>tasks.some(t=>t.projectId===project?.id&&t.approvalStep===step&&t.status==='approved')))return toast('ابتدا تأیید فنی و تجاری را از میز کار تکمیل کنید.');if(!project)return;const allowed={Draft:['Estimate'],Estimate:['Draft','Approved'],Approved:['Contracted'],Contracted:['Archived'],Archived:[]};if(!(allowed[project.status||'Estimate']||[]).includes(nextStatus))return toast('انتقال وضعیت مجاز نیست.');if(nextStatus==='Approved'&&(!project.lines.length||allLeaves.some(n=>!activeQ(n))))return toast('برای تصویب، ساختار باید جزء داشته باشد و همه اقلام قیمت معتبر انتخاب‌شده داشته باشند.');if(!confirm('تغییر وضعیت پروژه به «'+statusFa[nextStatus]+'» ثبت شود؟'+(nextStatus==='Approved'?' یک Baseline تغییرناپذیر هم ثبت می‌شود.':'')))return;const snapshot=nextStatus==='Approved'?{id:uid('BASE'),createdAt:new Date().toISOString(),root:clone(project.lines),definitions:clone(assemblies),items:clone(items),priceLines:allLeaves.map(n=>({path:n.path,itemId:n.ref,qty:n.qty,effectiveQty:qtyOnPath(n.path),quotation:clone(activeQ(n))})),total:totalNow}:null;persist(d=>{const p=d.projects.find(x=>x.id===project.id);p.status=nextStatus;if(snapshot){p.baselines||=[];p.baselines.push(snapshot)}});setChosen([]);toast('وضعیت پروژه تغییر کرد و در تاریخچه ثبت شد.')}
 function newRevision(){if(!project)return;if(activeRole==='owner'&&project.ownerName!==actor.trim())return toast('این پروژه متعلق به مالک دیگری است.');if(activeRole==='head_owner'&&!inManagerScope(project))return toast('پروژه خارج از حوزه مدیریتی است.');const old=project;if(!confirm('یک نسخه کاری مستقل از پروژه ایجاد شود؟ نسخه فعلی بدون تغییر می‌ماند.'))return;const id=uid('PRJ');const rev=String(Number(old.revision||0)+1).padStart(2,'0');persist(d=>{const p=clone(old);p.id=id;p.name=old.name+' — بازنگری '+rev;p.sourceId=old.id;p.revision=rev;p.status='Draft';p.baselines=[];p.estimateHistory=[];p.createdFromApprovedAt=new Date().toISOString();const map=new Map();function duplicateLinked(ref){if(map.has(ref))return map.get(ref);const src=d.assemblies.find(a=>a.id===ref);if(!src)return ref;const newId=uid(src.type==='system'?'SYS':'MOD');map.set(ref,newId);const next=clone(src);next.id=newId;next.name=src.name+' — نسخه '+rev;next.sourceId=src.id;next.revision=rev;next.lines=next.lines.map(line=>line.kind==='assembly'?{...line,ref:duplicateLinked(line.ref),mode:'duplicate'}:line);d.assemblies.push(next);return newId}p.lines=p.lines.map(l=>l.kind==='assembly'?{...l,ref:duplicateLinked(l.ref),mode:'duplicate'}:l);d.projects.push(p);d.tasks||=[];for(const [step,assigneeRole,title] of [['technical','tech_manager','تأیید فنی نسخه جدید'],['commercial','commercial_manager','تأیید تجاری نسخه جدید']])d.tasks.push({id:uid('TASK'),title,projectId:id,assigneeRole,owner:actor,priority:'بالا',deadline:'',status:'open',approvalStep:step});});setSelectedProject(id);setChosen([]);toast('نسخه کاری مستقل با ساختار ماژول‌های جدا ساخته شد.') }
 function addTask(e){e.preventDefault();if(!canRole('tasks'))return toast('مجوز تعریف کار ندارید.');const form=new FormData(e.currentTarget),task={id:uid('TASK'),title:String(form.get('title')),projectId:String(form.get('projectId')),assigneeRole:String(form.get('assigneeRole')),owner:actor,deadline:String(form.get('deadline')||''),priority:String(form.get('priority')),status:'open',createdAt:new Date().toISOString(),approvalStep:''};persist(d=>{d.tasks||=[];d.tasks.push(task)});e.currentTarget.reset();toast('وظیفه ثبت و به میز کار نقش مربوط ارجاع شد.')}
 function updateTask(id,status){persist(d=>{const task=(d.tasks||[]).find(t=>t.id===id);if(task&&task.assigneeRole===activeRole)task.status=status});toast('وضعیت وظیفه ثبت شد.')}
 function decideApproval(id,decision){const t=tasks.find(x=>x.id===id);if(!t||t.assigneeRole!==activeRole)return toast('این تأیید به نقش دیگری سپرده شده است.');const taskProject=projects.find(p=>p.id===t.projectId);if(!taskProject||!EDITABLE.includes(taskProject.status))return toast('این پروژه در وضعیت قابل تأیید نیست.');if(!taskProject.lines?.length&&decision==='approved')return toast('BOM پروژه هنوز خالی است.');persist(d=>{const task=(d.tasks||[]).find(x=>x.id===id);task.status=decision;task.decidedBy=actor;task.decidedAt=new Date().toISOString()});toast(decision==='approved'?'تأیید ثبت شد.':'درخواست برای اصلاح برگشت خورد.')}
 const myTasks=tasks.filter(t=>t.assigneeRole===activeRole&&(activeRole!=='owner'||!t.assigneeName||t.assigneeName===actor.trim()));
 const pendingTasks=myTasks.filter(t=>!['done','approved','rejected'].includes(t.status));
 useEffect(()=>{if(activeRole!=='head_owner'&&tab==='portfolio')setTab('dashboard')},[activeRole,tab]);
 const nav=[['dashboard','میز کار من',LayoutDashboard],['tasks','وظایف و تأییدها',CheckCircle2],['roles','نقش‌ها و دسترسی‌ها',Users],...(activeRole==='head_owner'?[['portfolio','مدیریت مالکین محصول',Users]]:[]),['items','بانک اقلام',Package],['assemblies','ماژول‌ها و سامانه‌ها',Boxes],['suppliers','تأمین‌کنندگان',Users],['quotations','استعلام قیمت',Receipt],['projects','پروژه‌ها و BOM',GitBranch],['history','نسخه‌های پروژه',History],['audit','تاریخچه تغییرات',History],['reference','سند مرجع',FileJson]];
 function treeRow(n,depth=0,mult=1){const leaf=n.kind==='item',q=activeQ(n),latest=latestQuote(n.ref),hasChange=leaf&&eligible(n),childChanged=leaf?(hasChange?[n.path]:[]):leavesOf(n).filter(eligible).map(l=>l.path),isOpen=expanded[n.path]??depth<2, checked=childChanged.length>0&&childChanged.every(p=>chosen.includes(p)),partial=childChanged.some(p=>chosen.includes(p))&&!checked;let effectiveQty=mult*n.qty;const lineCost=leaf?effectiveQty*(q?.price||0):total(n.children,effectiveQty);const label=n.def?.name||'موجودیت یافت نشد';return <React.Fragment key={n.path}><div className={'tree-row '+(leaf?'leaf':'parent')} style={{paddingRight:`${12+depth*19}px`}}><button className="chev" onClick={()=>setExpanded(v=>({...v,[n.path]:!isOpen}))} disabled={leaf}>{leaf?<span className="dot"/>:isOpen?<ChevronDown size={16}/>:<ChevronLeft size={16}/>}</button><div className="tree-text"><button className="profile-link tree-title" onClick={()=>{setProfile({type:leaf?'item':n.def?.type,id:n.ref});setTab('profile')}}>{label}</button><span className="muted code">{n.def?.id||n.ref} {n.mode?'• '+n.mode:''}</span></div><label className="tree-qty" title="تعداد مستقیم این جزء در ساختار جاری"><span>تعداد در سطح جاری</span><input type="number" min="0.001" step="0.001" key={`${n.parentId}-${n.id}-${n.qty}`} defaultValue={n.qty} disabled={!canEditReadonly(n.parentId)||(!canRole('assemblies')&&!canRole('projects'))} onBlur={e=>updateQty(n.parentId,n.id,e.target.value)} onKeyDown={e=>{if(e.key==='Enter')e.currentTarget.blur()}}/></label><span className="tree-effective" title="حاصل‌ضرب تعداد در تمام سطوح بالادستی">تعداد کل: <strong>{money(effectiveQty)}</strong></span><span className="tree-cost">{money(lineCost)} <small>تومان</small></span>{hasChange&&<span className={'pill '+(latest.price>q.price?'red':'green')}>{latest.price>q.price?'افزایش':'کاهش'} {money(Math.abs(latest.price-q.price))}</span>}{!leaf&&childChanged.length>0&&<span className="pill amber">{childChanged.length} تغییر</span>}{canEditReadonly(n.parentId)&&<button className="btn compact danger-btn" title="حذف ردیف از BOM" onClick={()=>removeLine(n.parentId,n.id)}><Trash2 size={14}/></button>}{childChanged.length>0&&<label className="check"><input type="checkbox" checked={checked} ref={el=>{if(el)el.indeterminate=partial}} onChange={e=>toggleSelect(childChanged,e.target.checked)}/><span>انتخاب</span></label>}</div>{leaf&&hasChange&&isOpen&&<div/>}{!leaf&&isOpen&&n.children.map(c=>treeRow(c,depth+1,effectiveQty))}</React.Fragment>}
 function itemLabel(id){const it=items.find(i=>i.id===id);return it?it.name:id}
 const stats=[['اقلام یکتا',items.length,Package],['ماژول‌ها',assemblies.filter(a=>a.type==='module').length,Boxes],['سامانه‌ها',assemblies.filter(a=>a.type==='system').length,Boxes],['استعلام‌ها',quotes.length,Receipt],['پروژه‌ها',projects.length,GitBranch]];
 if(!data)return <div className="loading">در حال بارگذاری اطلاعات نمونه BOM… {notice}</div>;
 return <div className="app"><aside className={'sidebar '+(mobileMenu?'show':'')}><div className="brand"><div className="brandmark">B</div><div><b>BOM App</b><small>نسخه آزمایشی 1.0</small></div><button className="mobile-close" onClick={()=>setMobileMenu(false)}><X/></button></div><div className="nav-label">مدیریت مهندسی</div><nav>{nav.map(([key,title,I])=><button key={key} className={'nav-item '+(tab===key?'active':'')} onClick={()=>{setTab(key);setMobileMenu(false);setSearch('')}}><I size={18}/>{title}</button>)}</nav><div className="sidebar-note">داده‌ها فعلاً در حافظه همین مرورگر ذخیره می‌شوند. برای انتقال، خروجی JSON بگیرید.</div></aside><div className="work"><header><div className="head-name"><button className="hamb" onClick={()=>setMobileMenu(true)}><Menu/></button><h1>{nav.find(x=>x[0]===tab)?.[1]}</h1><span>دموی بدون دیتابیس</span></div><div className="head-actions"><label className="actor-field">نقش آزمایشی <select value={activeRole} onChange={e=>{setActiveRole(e.target.value);localStorage.setItem('bom-demo-role',e.target.value)}}>{Object.entries(ROLES).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><label className="actor-field">ثبت‌کننده تغییرات <input value={actor} onChange={e=>{setActor(e.target.value);localStorage.setItem('bom-demo-actor',e.target.value)}} placeholder="نام کاربر"/></label><button className="btn ghost" onClick={downloadJson}><Download size={16}/> خروجی JSON</button><label className="btn ghost"><Upload size={16}/> ورود JSON <input hidden type="file" accept=".json,application/json" onChange={e=>{importJson(e.target.files?.[0]);e.target.value=''}}/></label></div></header><main>{notice&&<div className="notice"><AlertTriangle size={17}/>{notice}</div>}
 {tab==='dashboard'&&<><div className="panel role-welcome"><h3>میز کار {ROLES[activeRole]}</h3><p>وظایف محول‌شده، تأییدهای در انتظار و بخش‌های مجاز را در این صفحه ببینید. نقش‌ها در این دمو شبیه‌سازی شده‌اند.</p><div className="role-kpis"><div><strong>{myTasks.length}</strong><span>همه وظایف من</span></div><div><strong>{pendingTasks.length}</strong><span>نیازمند اقدام</span></div><div><strong>{myTasks.filter(t=>t.status==='approved'||t.status==='done').length}</strong><span>انجام‌شده / تأییدشده</span></div></div><div className="task-actions"><button className="btn primary" onClick={()=>setTab('tasks')}>مشاهده وظایف و تأییدها</button><button className="btn ghost" onClick={()=>setTab('reference')}>مطالعه سند مرجع</button></div>{pendingTasks.slice(0,5).map(t=><div key={t.id} className="task-line"><span>{t.title}</span><span>{projects.find(p=>p.id===t.projectId)?.name||t.projectId}</span><button className="btn compact" onClick={()=>setTab('tasks')}>بررسی</button></div>)}</div>{activeRole==='head_owner'&&<div className="panel"><h3>سبد پروژه‌های تحت مدیریت من</h3><p className="hint">فقط پروژه‌هایی که نام مدیر مسئول آن‌ها با نام کاربر فعال منطبق است در محدوده مدیریتی قرار می‌گیرند. پروژه‌های فاقد مدیر نیاز به تخصیص اولیه دارند.</p><div className="role-kpis"><div><strong>{managedProjects(projects).length}</strong><span>پروژه‌های تحت مدیریت</span></div><div><strong>{managedProjects(projects).filter(p=>p.status==='Estimate').length}</strong><span>در مرحله برآورد</span></div><div><strong>{managedProjects(projects).filter(p=>p.status==='Approved').length}</strong><span>مصوب</span></div></div><button className="btn primary" onClick={()=>setTab('portfolio')}>مدیریت مالکین و پروژه‌ها</button></div>}<div className="hero"><span className="eyebrow">ENGINEERING BOM MANAGER</span><h2>مدیریت یکپارچه اقلام، ساختار و قیمت</h2><p>از قطعه تا ماژول، سامانه و پروژه — همراه با استعلام‌های تاریخی و قیمت‌گذاری مستقل هر محل استفاده.</p><button className="btn primary" onClick={()=>setTab('projects')}>مشاهده درخت پروژه <ChevronLeft size={17}/></button></div><div className="stats">{stats.map(([name,v,I])=><div className="stat" key={name}><I size={20}/><strong>{money(v)}</strong><span>{name}</span></div>)}</div><div className="panel"><h3>قابلیت‌های فعال دمو</h3><div className="features">{['ساختار BOM بازگشتی','Reference / Duplicate','قیمت مستقل در وقوع','انتخاب گروهی قیمت','قفل Snapshot تاریخی','ورود و خروجی JSON'].map(x=><div key={x}><CheckCircle2 size={17}/>{x}</div>)}</div></div></>}
 {tab==='reference'&&<div className="panel"><div className="panel-head"><div><h3>سند مرجع جامع معماری و نیازمندی‌های BOM</h3><p className="hint">نسخه جامع فارسی شامل ۲۱ فصل، معماری، نمونه BOM، سناریوهای تغییر قیمت، نقش‌ها و گردش تأیید</p></div><div className="actions"><a className="btn primary" href={`${import.meta.env.BASE_URL}docs/BOM_Reference_Architecture.html`} target="_blank" rel="noopener noreferrer">باز کردن در صفحه جدید</a><a className="btn ghost" href={`${import.meta.env.BASE_URL}docs/BOM_Reference_Architecture.html`} download>دریافت HTML</a></div></div><iframe title="سند مرجع BOM" className="reference-frame" src={`${import.meta.env.BASE_URL}docs/BOM_Reference_Architecture.html`} loading="lazy"/></div>}
 {tab==='profile'&&profile&&(()=>{const entity=(profile.type==='item'?items:profile.type==='project'?projects:assemblies).find(x=>x.id===profile.id);if(!entity)return <div className="panel">موجودیت یافت نشد.<button className="btn" onClick={()=>setTab('dashboard')}>بازگشت</button></div>;const isItem=profile.type==='item';const isProject=profile.type==='project';const section=isItem?'items':isProject?'projects':'assemblies';const logs=(data.audit||[]).filter(a=>a.entityId===entity.id||a.projectIds?.includes(entity.id)).slice().reverse().slice(0,20);const editable=isItem?canRole('items'):isProject?canRole('projects')&&EDITABLE.includes(entity.status):canRole('assemblies')&&canEditReadonly(entity.id);return <><div className="section-bar"><div><button className="btn compact" onClick={()=>setTab(section)}>بازگشت به فهرست</button><h2>{entity.name}</h2><p className="hint">{entity.id} · {isItem?'قلم':isProject?'پروژه':profile.type==='module'?'ماژول':'سامانه'} · Rev {entity.revision||'—'}</p></div><span className="pill amber">{isProject?statusFa[entity.status]||entity.status:'صفحه مشخصات'}</span></div><div className="profile-grid"><div className="panel"><h3>تصویر و مدارک</h3>{entity.imageUrl?<img className="profile-photo" src={entity.imageUrl} alt={entity.name} onError={e=>{e.currentTarget.style.display='none'}}/>:<div className="profile-placeholder"><Package size={45}/><span>تصویری ثبت نشده است</span></div>}{entity.datasheetUrl&&<p><a href={entity.datasheetUrl} target="_blank" rel="noreferrer">مشاهده دیتاشیت / سند فنی ↗</a></p>}<p className="hint">در نسخه آزمایشی آدرس فایل ذخیره می‌شود. بارگذاری و نگهداری واقعی فایل‌ها در نسخه Backend پیاده‌سازی خواهد شد.</p></div><div className="panel"><h3>شناسنامه و مشخصات فنی</h3><form key={entity.id} className="profile-form" onSubmit={e=>{e.preventDefault();if(!editable)return toast('مجوز ویرایش این موجودیت را ندارید یا نسخه قفل است.');const f=new FormData(e.currentTarget);let attrs={};try{attrs=JSON.parse(f.get('attributes')||'{}');if(!attrs||typeof attrs!=='object'||Array.isArray(attrs))throw Error('attributes')}catch{return toast('مشخصات فنی باید JSON معتبر از نوع شیء باشد.')}persist(d=>{const list=isItem?d.items:isProject?d.projects:d.assemblies;const entry=list.find(x=>x.id===entity.id);for(const key of ['description','imageUrl','datasheetUrl','notes'])entry[key]=String(f.get(key)||'');entry.attributes=attrs});toast('مشخصات صفحه ذخیره و در تاریخچه ثبت شد.')}}><label>توضیحات<textarea name="description" rows="3" defaultValue={entity.description||''}/></label><label>مشخصات فنی قابل توسعه (JSON)<textarea className="mono" name="attributes" rows="5" dir="ltr" defaultValue={JSON.stringify(entity.attributes||{},null,2)}/></label><label>آدرس تصویر<input name="imageUrl" type="url" dir="ltr" defaultValue={entity.imageUrl||''} placeholder="https://..."/></label><label>آدرس دیتاشیت / فایل<input name="datasheetUrl" type="url" dir="ltr" defaultValue={entity.datasheetUrl||''} placeholder="https://..."/></label><label>یادداشت‌ها<textarea name="notes" rows="2" defaultValue={entity.notes||''}/></label><button className="btn primary" disabled={!editable}><Save size={16}/> ذخیره تغییرات</button>{!editable&&<p className="hint">این صفحه به علت نقش فعلی یا وضعیت مصوب، فقط خواندنی است.</p>}</form></div></div><div className="panel"><h3>{isItem?'استعلام‌های مربوط به قلم': 'ساختار BOM و تعداد اجزا'}</h3>{isItem?<div className="scroll"><table><thead><tr><th>تأمین‌کننده</th><th>قیمت واحد</th><th>تاریخ</th></tr></thead><tbody>{quotes.filter(q=>q.itemId===entity.id).map(q=><tr key={q.id}><td>{suppliers.find(s=>s.id===q.supplierId)?.name||q.supplierId}</td><td>{money(q.price)} {q.currency}</td><td>{q.date}</td></tr>)}</tbody></table></div>:<div className="scroll"><table><thead><tr><th>جزء</th><th>نوع</th><th>تعداد در سطح جاری</th></tr></thead><tbody>{(entity.lines||[]).map(l=><tr key={l.id}><td><button className="profile-link" onClick={()=>setProfile({type:l.kind==='item'?'item':defById(l.ref)?.type||'module',id:l.ref})}>{l.kind==='item'?itemLabel(l.ref):defById(l.ref)?.name||l.ref}</button></td><td>{l.kind==='item'?'قلم':defById(l.ref)?.type==='system'?'سامانه':defById(l.ref)?.type==='project'?'پروژه':'ماژول'}</td><td>{money(l.qty)}</td></tr>)}{!(entity.lines||[]).length&&<tr><td colSpan="3">هنوز جزء ثبت نشده است.</td></tr>}</tbody></table></div>}</div>{isProject&&<div className="panel"><h3>مدیریت پروژه</h3><div className="actions"><button className="btn primary" onClick={()=>{setSelectedProject(entity.id);setTab('projects')}}>ورود به BOM و گردش تأیید</button><button className="btn" onClick={()=>{setHistoryProject(entity.id);setTab('history')}}>نسخه‌های پروژه</button><button className="btn ghost" onClick={()=>{setHistoryProject(entity.id);setTab('audit')}}>تاریخچه کامل تغییرات</button></div></div>}<div className="panel"><h3>آخرین سوابق تغییر</h3>{logs.length?logs.map(a=><div className="profile-event" key={a.id}><b>{a.action}</b> · {a.actor} · {new Date(a.timestamp).toLocaleString('fa-IR')}<small>{a.field}</small></div>):<p className="hint">هنوز تغییری در تاریخچه ثبت نشده است.</p>}</div></>})()}
 {tab==='portfolio'&&activeRole==='head_owner'&&<div className="panel"><h3>مدیریت مالکین محصول و تخصیص مسئولیت پروژه</h3><p className="hint">برای تعیین مالک محصول هر پروژه، ابتدا نام مدیر مالکین محصول را در سربرگ وارد کنید. تغییرات نام مالک و مدیر پروژه همراه با نام ثبت‌کننده و زمان در تاریخچه ثبت می‌شوند. در نسخه دمو پروژه‌های فاقد مدیر قابل تخصیص اولیه‌اند؛ پروژه‌های متعلق به مدیر دیگر قابل تغییر نیستند.</p>{activeRole!=='head_owner'?<div className="empty">این بخش فقط با نقش «مدیر مالکین محصول» قابل استفاده است.</div>:<div className="scroll"><table><thead><tr><th>پروژه</th><th>مالک محصول مسئول</th><th>مدیر مسئول</th><th>وضعیت</th><th>تخصیص / انتقال مسئولیت</th></tr></thead><tbody>{projects.map(p=><tr key={p.id}><td>{p.name}<small className="muted ltr"> {p.id}</small></td><td>{p.ownerName||'تعیین نشده'}</td><td>{p.managerName||'تعیین نشده'}</td><td>{statusFa[p.status]||p.status}</td><td>{(!p.managerName||p.managerName===actor.trim())?<form className="ownership-form" onSubmit={e=>{e.preventDefault();assignOwner(p.id,new FormData(e.currentTarget).get('newOwner'))}}><input name="newOwner" required defaultValue={p.ownerName||''} placeholder="نام مالک مسئول" aria-label="نام مالک مسئول"/><button className="btn compact" type="submit">ثبت مسئولیت</button></form>:<span className="muted">خارج از حوزه مدیریتی</span>}</td></tr>)}</tbody></table></div>}<p className="hint">انتقال پروژه با تغییر مالک محصول انجام می‌شود؛ سوابق قبلی مالک و نسخه‌های تصویب‌شده حفظ می‌شوند. گزارش‌های پیشرفته و احراز هویت در نسخه سروری تکمیل خواهند شد.</p></div>}
 {tab==='roles'&&<><div className="panel"><h3>نقش‌های سامانه و محدوده دسترسی</h3><p className="hint">این مجوزها مبنای پیشنهادی طراحی هستند. در دمو تنها محدودسازی رابط و عملیات انجام می‌شود؛ امنیت واقعی به Backend و احراز هویت نیاز دارد.</p><div className="scroll"><table><thead><tr><th>نقش</th><th>کارها و مسئولیت‌ها</th><th>مجوزهای نمونه</th></tr></thead><tbody>{Object.entries(ROLES).map(([id,name])=><tr key={id}><td>{name}</td><td>{({owner:'پیگیری و ویرایش پروژه‌های تخصیص‌یافته، ارجاع کار و تصویب نهایی پس از تأییدها؛ بدون اختیار ایجاد پروژه',head_owner:'ایجاد پروژه و تعیین مالک محصول هر پروژه، تمام اختیارات مالک محصول در حوزه خود، انتقال مالک، گزارش تجمیعی و رسیدگی به ارجاعات',tech_manager:'نظارت فنی و تأیید BOM',tech:'تعریف اقلام و اصلاح ساختار BOM',commercial_manager:'تأیید تجاری و قیمت‌ها',commercial:'ثبت RFQ، پیش‌فاکتور و استعلام',admin:'مدیریت حساب‌ها و تنظیمات'}[id])}</td><td>{(PERMISSIONS[id]||[]).join(' / ')}</td></tr>)}</tbody></table></div></div></>}
 {tab==='tasks'&&<><div className="panel"><div className="panel-head"><h3>وظایف، ارجاع کار و تأییدهای مرحله‌ای</h3><label>نمایش <select value={taskFilter} onChange={e=>setTaskFilter(e.target.value)}><option value="mine">وظایف نقش من</option><option value="all">تمام وظایف</option></select></label></div><p className="hint">تأیید فنی و تجاری به صورت دو وظیفه مستقل ثبت می‌شوند؛ ثبت تصویب نهایی منوط به تأیید هر دو است.</p><div className="scroll"><table><thead><tr><th>کار</th><th>پروژه</th><th>مسئول</th><th>اولویت / مهلت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody>{tasks.filter(t=>taskFilter==='all'||t.assigneeRole===activeRole).map(t=><tr key={t.id}><td><b>{t.title}</b><div className="muted ltr">{t.id}</div></td><td>{projects.find(p=>p.id===t.projectId)?.name||t.projectId}</td><td>{ROLES[t.assigneeRole]}</td><td>{t.priority||'عادی'} / {t.deadline||'—'}</td><td>{({open:'باز',doing:'در حال انجام',done:'انجام شد',approved:'تأیید شد',rejected:'نیاز به اصلاح'}[t.status]||t.status)}</td><td>{t.assigneeRole===activeRole&&<div className="actions">{t.approvalStep?<><button className="btn compact" onClick={()=>decideApproval(t.id,'approved')}>تأیید</button><button className="btn compact danger-btn" onClick={()=>decideApproval(t.id,'rejected')}>برگشت</button></>:<><button className="btn compact" onClick={()=>updateTask(t.id,'doing')}>شروع</button><button className="btn compact" onClick={()=>updateTask(t.id,'done')}>اتمام</button></>}</div>}</td></tr>)}</tbody></table></div></div><div className="panel"><h3>ارجاع وظیفه جدید</h3><form className="formgrid" onSubmit={addTask}><label>عنوان کار<input name="title" required placeholder="مثلاً بررسی BOM ماژول گیرنده"/></label><label>پروژه<select name="projectId">{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label><label>نقش مسئول<select name="assigneeRole">{Object.entries(ROLES).filter(([id])=>id!=='admin').map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><label>اولویت<select name="priority"><option>عادی</option><option>بالا</option><option>فوری</option></select></label><label>مهلت<input type="date" name="deadline"/></label><button className="btn primary">ثبت و ارجاع</button></form></div></>}
 {tab==='items'&&<><div className="section-bar"><p>کاتالوگ یکتای اقلام با کنترل تکراری بودن سازنده و شماره قطعه</p><div className="search"><Search size={17}/><input placeholder="جستجوی نام، MPN، کد…" value={search} onChange={e=>setSearch(e.target.value)}/></div></div><div className="panel"><div className="scroll"><table><thead><tr><th>شناسه</th><th>نام قلم</th><th>Part Number</th><th>سازنده</th><th>نوع</th><th>استعلام‌ها</th></tr></thead><tbody>{items.filter(i=>clean(JSON.stringify(i)).includes(clean(search))).map(i=><tr key={i.id}><td className="ltr">{i.id}</td><td><button className="profile-link" onClick={()=>{setProfile({type:'item',id:i.id});setTab('profile')}}>{i.name}</button></td><td className="ltr">{i.mpn}</td><td className="ltr">{i.manufacturer}</td><td>{i.category}</td><td>{quotes.filter(q=>q.itemId===i.id).length}</td></tr>)}</tbody></table></div></div><div className="panel"><h3>ثبت قلم جدید</h3><form onSubmit={addItem} className="formgrid"><label>نام قلم<input name="name" required/></label><label>شماره فنی MPN<input name="mpn" required dir="ltr"/></label><label>سازنده<input name="manufacturer" required/></label><label>گروه<input name="category" placeholder="IC / RF / Passive"/></label><button className="btn primary"><Plus size={16}/> ثبت قلم</button></form></div></>}
 {tab==='suppliers'&&<><div className="panel"><h3>تأمین‌کنندگان</h3><div className="scroll"><table><thead><tr><th>کد</th><th>نام</th><th>شهر</th><th>ارتباط</th></tr></thead><tbody>{suppliers.map(s=><tr key={s.id}><td className="ltr">{s.id}</td><td>{s.name}</td><td>{s.city}</td><td className="ltr">{s.contact}</td></tr>)}</tbody></table></div></div><div className="panel"><h3>ثبت تأمین‌کننده</h3><form className="formgrid" onSubmit={addSupplier}><label>نام<input name="name" required/></label><label>شهر<input name="city"/></label><label>اطلاعات تماس<input name="contact"/></label><button className="btn primary"><Plus size={16}/> افزودن</button></form></div></>}
 {tab==='quotations'&&<><div className="panel"><h3>تاریخچه استعلام قیمت</h3><p className="hint">اطلاعات نمونه و قیمت‌ها فرضی هستند؛ قیمت‌های جدید جایگزین رکوردهای قدیمی نمی‌شوند.</p><div className="scroll"><table><thead><tr><th>کد</th><th>قلم</th><th>تأمین‌کننده</th><th>قیمت واحد</th><th>تاریخ</th><th>اعتبار</th></tr></thead><tbody>{quotes.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(q=><tr key={q.id}><td className="ltr">{q.id}</td><td>{itemLabel(q.itemId)}</td><td>{suppliers.find(s=>s.id===q.supplierId)?.name||q.supplierId}</td><td>{money(q.price)} {q.currency}</td><td className="ltr">{q.date}</td><td className="ltr">{q.validUntil}</td></tr>)}</tbody></table></div></div><div className="panel"><h3>ثبت استعلام جدید</h3><form className="formgrid" onSubmit={addQuotation}><label>قلم<select name="itemId" required>{items.map(i=><option value={i.id} key={i.id}>{i.id} — {i.name}</option>)}</select></label><label>تأمین‌کننده<select name="supplierId" required>{suppliers.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>قیمت واحد (تومان)<input name="price" type="number" min="0" required/></label><label>حداقل تعداد<input name="minQty" type="number" min="1" defaultValue="1"/></label><label>تاریخ استعلام<input name="date" type="date" defaultValue={new Date().toISOString().slice(0,10)} required/></label><label>معتبر تا<input name="validUntil" type="date" defaultValue="2027-01-01" required/></label><button className="btn primary"><Plus size={16}/> ثبت استعلام</button></form></div></>}
 {tab==='assemblies'&&<><div className="section-bar"><p>ساختارها قابل ارجاع هستند؛ Duplicate شناسه جدید و BOM مستقل ایجاد می‌کند.</p></div><div className="panel"><h3>کتابخانه ماژول‌ها و سامانه‌ها</h3><div className="scroll"><table><thead><tr><th>کد</th><th>عنوان</th><th>نوع</th><th>Rev</th><th>ردیف‌های BOM</th><th>جمع تعداد مستقیم</th><th>جزئیات و تعداد اقلام / ماژول‌ها</th><th>عملیات</th></tr></thead><tbody>{assemblies.map(a=><tr key={a.id}><td className="ltr">{a.id}</td><td><button className="profile-link" onClick={()=>{setProfile({type:a.type,id:a.id});setTab('profile')}}>{a.name}</button></td><td>{a.type==='module'?'ماژول':'سامانه'}</td><td>{a.revision}</td><td>{a.lines.length}</td><td>{money(a.lines.reduce((sum,l)=>sum+Number(l.qty||0),0))}</td><td><details className="assembly-details"><summary>مشاهده اجزا ({a.lines.length} ردیف)</summary><ul>{a.lines.map(l=><li key={l.id}><b>{money(l.qty)} ×</b> {l.kind==='item'?itemLabel(l.ref):defById(l.ref)?.name||l.ref} <small className="ltr">({l.ref})</small></li>)}</ul></details></td><td><button className="btn compact" onClick={()=>duplicateAssembly(a.id)}><Copy size={15}/> Duplicate</button></td></tr>)}</tbody></table></div></div><div className="panel"><h3>ساخت ماژول یا سامانه جدید</h3><form onSubmit={addAssembly} className="formgrid"><label>نام<input name="name" required/></label><label>نوع<select name="type"><option value="module">Module</option><option value="system">System</option></select></label><button className="btn primary"><Plus size={16}/> ایجاد</button></form></div><AddLineForm {...{items,assemblies,projects,addLine,canEditReadonly}}/></>}
 {tab==='projects'&&<><div className="panel project-directory"><div className="panel-head"><div><h3>پروژه‌های ثبت‌شده</h3><p className="hint">{activeRole==='owner'?'پروژه‌های متعلق به شما با نام ثبت‌کننده بالای صفحه مشخص می‌شوند؛ ویرایش سایر پروژه‌ها مجاز نیست. ':''}برای باز کردن شناسنامه، روی «صفحه اختصاصی» کلیک کنید؛ برای مدیریت BOM گزینه «مشاهده BOM» را بزنید.</p></div></div><div className="project-directory-grid">{projects.map(p=><div className={'project-directory-card '+(project?.id===p.id?'selected':'')} key={p.id}><div className="project-directory-head"><strong>{p.name}</strong><span className="pill amber">{statusFa[p.status]||p.status}</span></div><small dir="ltr">{p.id} · Rev {p.revision||'00'}</small><small className="muted">مالک مسئول: {p.ownerName||'تعیین نشده'} | مدیر مالکین: {p.managerName||'تعیین نشده'}</small><div className="project-directory-actions"><button className="btn primary compact" onClick={()=>{setProfile({type:'project',id:p.id});setSelectedProject(p.id);setTab('profile')}}>صفحه اختصاصی پروژه</button><button className="btn compact" onClick={()=>{setSelectedProject(p.id);setChosen([])}}>مشاهده BOM</button></div></div>)}</div></div><div className="section-bar"><div><p>ویرایش درخت و انتخاب تغییرات قیمت، مستقل از کاتالوگ مرکزی</p><select className="project-select" value={project?.id} onChange={e=>{setSelectedProject(e.target.value);setChosen([])}}>{projects.map(p=><option key={p.id} value={p.id}>{p.id} — {p.name}</option>)}</select><button className="btn compact" onClick={()=>{if(project){setProfile({type:'project',id:project.id});setTab('profile')}}}>باز کردن شناسنامه پروژه انتخاب‌شده</button></div><span className="pill amber">{statusFa[project?.status]||project?.status||'Estimate'}</span></div><div className="panel workflow-panel"><h3>گردش وضعیت و نهایی‌سازی پروژه</h3><p className="hint">وضعیت فعلی: <b>{statusFa[project?.status]||project?.status}</b> — هنگام تصویب، Snapshot هزینه و ساختار ثبت و نسخه جاری قفل می‌شود. برای تغییرات بعدی نسخه کاری مستقل بسازید.</p><div className="actions">{project?.status==='Draft'&&<button className="btn primary" onClick={()=>transitionStatus('Estimate')}>ارسال به برآورد</button>}{project?.status==='Estimate'&&<><button className="btn" onClick={()=>transitionStatus('Draft')}>بازگشت به پیش‌نویس</button><button className="btn primary" onClick={()=>transitionStatus('Approved')}>تأیید نهایی و ثبت Baseline</button></>}{project?.status==='Approved'&&<button className="btn primary" onClick={()=>transitionStatus('Contracted')}>ثبت وضعیت قراردادی</button>}{project?.status==='Contracted'&&<button className="btn" onClick={()=>transitionStatus('Archived')}>بایگانی پروژه</button>}{!projectEditable&&<button className="btn" onClick={newRevision}>ساخت Revision کاری جدید</button>}<button className="btn ghost" onClick={()=>{setHistoryProject(project.id);setTab('audit')}}>مشاهده تاریخچه پروژه</button></div></div><div className="stats pricing-stats"><div className="stat"><span>هزینه فعلی</span><strong>{money(totalNow)}</strong><small>تومان</small></div><div className="stat"><span>پس از انتخاب‌ها</span><strong>{money(totalPreview)}</strong><small>تومان</small></div><div className="stat"><span>تغییر خالص</span><strong className={totalPreview>totalNow?'danger':'success'}>{totalPreview>totalNow?'+':''}{money(totalPreview-totalNow)}</strong><small>تومان</small></div><div className="stat"><span>موارد دارای تغییر</span><strong>{changed.length}</strong><small>قلم در مسیر BOM</small></div></div><div className="panel"><div className="panel-head"><h3>ساختار درختی BOM</h3><div className="actions"><button className="btn compact" onClick={()=>toggleSelect(changed.map(c=>c.path),true)}>انتخاب همه تغییرات</button><button className="btn compact" onClick={()=>setChosen([])}>لغو انتخاب</button></div></div><p className="hint">«تعداد در سطح جاری» قابل ویرایش است؛ «تعداد کل» حاصل‌ضرب تعدادهای مسیر از پروژه تا آن ردیف است. به‌عنوان مثال ۲ ماژول × ۸ مقاومت = ۱۶ مقاومت. تغییر تعداد در ساختار Reference بر تمام استفاده‌های آن ساختار اثر می‌گذارد. قیمت‌ها فقط پس از تأیید اعمال می‌شوند.</p><div className="tree">{tree.map(n=>treeRow(n))}{tree.length===0&&<div className="empty">برای این پروژه هنوز هیچ جزء تعریف نشده است.</div>}</div><div className="panel-footer"><span>{chosen.length} تغییر انتخاب‌شده</span><button className="btn primary" disabled={!chosen.length||!projectEditable} onClick={applyPrices}><Save size={16}/> اعمال قیمت‌های انتخابی</button><button className="btn ghost" disabled={!projectEditable} onClick={baseline}><CheckCircle2 size={16}/> ثبت Cost Baseline</button></div></div><div className="panel"><h3>جزئیات تغییرات قابل بررسی</h3><div className="scroll"><table><thead><tr><th>مسیر</th><th>قلم</th><th>قیمت ثبت‌شده</th><th>آخرین استعلام</th><th>تعداد کل در پروژه</th><th>اثر واحد</th><th>اثر کل پروژه</th></tr></thead><tbody>{changed.map(n=><tr key={n.path}><td className="ltr">{n.path}</td><td>{itemLabel(n.ref)}</td><td>{money(activeQ(n)?.price)}</td><td>{money(latestQuote(n.ref)?.price)}</td><td>{money(qtyOnPath(n.path))}</td><td className={latestQuote(n.ref).price>activeQ(n).price?'danger':'success'}>{money(latestQuote(n.ref).price-activeQ(n).price)}</td><td className={latestQuote(n.ref).price>activeQ(n).price?'danger':'success'}>{money((latestQuote(n.ref).price-activeQ(n).price)*qtyOnPath(n.path))}</td></tr>)}{!changed.length&&<tr><td colSpan="7">قیمتی برای بررسی باقی نمانده است.</td></tr>}</tbody></table></div></div><AddLineForm {...{items,assemblies,projects,addLine,canEditReadonly}}/><div className="panel"><h3>ایجاد و تخصیص پروژه</h3><p className="hint">ایجاد پروژه فقط توسط مدیر مالکین محصول انجام می‌شود. انتخاب مالک مسئول اجباری است و پروژه با وضعیت پیش‌نویس در میز کار او قرار می‌گیرد.</p>{activeRole==='head_owner'?<form className="formgrid" onSubmit={addProject}><label>عنوان پروژه<input name="name" required placeholder="عنوان پروژه"/></label><label>مالک محصول مسئول<input name="ownerName" required placeholder="نام کامل مالک محصول"/></label><label>اولویت<select name="priority"><option>متوسط</option><option>بالا</option><option>پایین</option></select></label><label>توضیح اولیه<input name="description" placeholder="شرح کوتاه پروژه"/></label><button className="btn primary"><Plus size={16}/> ایجاد پروژه و تخصیص مالک</button></form>:<div className="empty">تعریف پروژه در اختیار مدیر مالکین محصول است. پس از تخصیص، مالک محصول می‌تواند پروژه خود را تکمیل و ویرایش کند.</div>}</div></>}
 {tab==='audit'&&<div className="panel"><div className="panel-head"><h3>ردیابی تغییرات و فعالیت‌ها</h3><button className="btn ghost" onClick={downloadJson}>دریافت تاریخچه همراه JSON</button></div><p className="hint">ثبت خودکار قبل و بعد هر تغییر، نام ثبت‌کننده، زمان دقیق و پروژه‌های متاثر؛ تغییر در ساختار مشترک در تاریخچه همه پروژه‌های وابسته درج می‌شود.</p><label className="audit-filter">فیلتر پروژه <select value={historyProject} onChange={e=>setHistoryProject(e.target.value)}><option value="">همه پروژه‌ها و تغییرات عمومی</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name} ({p.id})</option>)}</select></label><div className="scroll"><table><thead><tr><th>زمان</th><th>تغییردهنده</th><th>نوع تغییر</th><th>موجودیت</th><th>فیلد / مسیر</th><th>قبل</th><th>بعد</th></tr></thead><tbody>{(data.audit||[]).filter(a=>!historyProject||a.projectIds?.includes(historyProject)).slice().reverse().map(a=><tr key={a.id}><td className="ltr">{new Date(a.timestamp).toLocaleString('fa-IR')}</td><td>{a.actor}</td><td>{a.action}</td><td className="ltr">{a.entityId}</td><td className="ltr">{a.field}</td><td><details><summary>نمایش</summary><pre className="audit-json">{JSON.stringify(a.before,null,2)}</pre></details></td><td><details><summary>نمایش</summary><pre className="audit-json">{JSON.stringify(a.after,null,2)}</pre></details></td></tr>)}{!(data.audit||[]).some(a=>!historyProject||a.projectIds?.includes(historyProject))&&<tr><td colSpan="7">هنوز تغییری ثبت نشده است. رویدادهای جدید از این نسخه به بعد ثبت می‌شوند.</td></tr>}</tbody></table></div></div>}
 {tab==='history'&&<>
 <div className="panel history-intro"><div className="panel-head"><div><h3>تاریخچه و نسخه‌های پروژه</h3><p className="hint">هر نسخه، تصویری ثابت از ساختار و هزینه پروژه در زمان ثبت است. ثبت Snapshot به معنی تصویب رسمی نیست.</p></div><button className="btn ghost" onClick={downloadJson}><FileJson size={16}/> خروجی JSON</button></div>
 <label className="audit-filter">انتخاب پروژه <select value={historyProject||project?.id||''} onChange={e=>setHistoryProject(e.target.value)}>{projects.map(p=><option key={p.id} value={p.id}>{p.name} — {p.id}</option>)}</select></label>
 {(()=>{const p=projects.find(p=>p.id===(historyProject||project?.id))||project;if(!p)return <div className="empty">پروژه‌ای یافت نشد.</div>;const arr=p.baselines||[];const ev=(data.audit||[]).filter(a=>a.projectIds?.includes(p.id));const last=arr[arr.length-1];return <>
 <div className="history-summary"><div><span>وضعیت کنونی پروژه</span><strong>{statusFa[p.status]||p.status}</strong></div><div><span>نسخه ثبت‌شده</span><strong>{money(arr.length)}</strong></div><div><span>آخرین هزینه ثبت‌شده</span><strong>{last?money(last.total)+' تومان':'—'}</strong></div><div><span>رویدادهای قابل ردیابی</span><strong>{money(ev.length)}</strong></div></div>
 <div className="history-help"><b>راهنما:</b> «Snapshot» فقط ثبت یک تصویر از هزینه است؛ «نسخه مصوب» هنگام تغییر وضعیت به Approved ساخته می‌شود. ثبت چند Snapshot یکسان لزوماً به معنی تغییر پروژه نیست.</div>
 {arr.length?<div className="version-grid">{arr.slice().reverse().map((b,reversedIndex)=>{const i=arr.length-1-reversedIndex;const prev=arr[i-1];const diff=prev?Number(b.total||0)-Number(prev.total||0):null;const approvedEvent=ev.find(e=>e.action==='تغییر وضعیت'&&e.after==='Approved'&&Math.abs(new Date(e.timestamp)-new Date(b.createdAt))<15000);const actorEvent=ev.find(e=>e.action==='ثبت Baseline'&&Math.abs(new Date(e.timestamp)-new Date(b.createdAt))<15000);const approver=approvedEvent?.actor||actorEvent?.actor||'ثبت‌کننده نامشخص';return <article key={b.id} className="version-card"><div className="version-head"><div><span className="version-number">نسخه ثبت‌شده {money(i+1)}</span><span className={'version-type '+(approvedEvent?'approved':'manual')}>{approvedEvent?'مصوب':'Snapshot / ذخیره موقت'}</span></div><small>{new Date(b.createdAt).toLocaleString('fa-IR')}</small></div><h4>{money(b.total)} <small>تومان</small></h4><div className="version-meta"><span>ثبت‌کننده: <b>{approver}</b></span><span>تعداد ردیف‌های اقلام: <b>{money(b.priceLines?.length||0)}</b></span><span>تفاوت هزینه با نسخه قبلی: <b className={diff>0?'danger':diff<0?'success':''}>{diff===null?'اولین نسخه':diff===0?'بدون تغییر هزینه':(diff>0?'+':'')+money(diff)+' تومان'}</b></span></div><details className="version-detail"><summary>مشاهده اقلام، تعدادها و قیمت‌های همین نسخه</summary><div className="scroll"><table><thead><tr><th>قلم</th><th>تعداد کل در پروژه</th><th>قیمت واحد زمان ثبت</th><th>هزینه ردیف</th></tr></thead><tbody>{(b.priceLines||[]).map((l,j)=><tr key={j}><td>{b.items?.find(it=>it.id===l.itemId)?.name||items.find(it=>it.id===l.itemId)?.name||l.itemId}</td><td>{money(l.effectiveQty)}</td><td>{money(l.quotation?.price)} تومان</td><td>{money(Number(l.effectiveQty||0)*Number(l.quotation?.price||0))} تومان</td></tr>)}</tbody></table></div><div className="version-id">شناسه فنی: {b.id}</div></details><button className="btn compact" onClick={()=>{setHistoryProject(p.id);setTab('audit')}}>مشاهده تاریخچه فعالیت‌های پروژه <ChevronLeft size={15}/></button></article>})}</div>:<div className="empty">هنوز نسخه‌ای ثبت نشده است. از بخش «پروژه‌ها و BOM» می‌توان Snapshot ثبت کرد یا پروژه را تأیید نهایی کرد.</div>}
 </>})()}
 </div>
 <div className="panel"><div className="panel-head"><h3>ردیابی همه تغییرات، جدا از نسخه‌های ثبت‌شده</h3><button className="btn primary" onClick={()=>{setHistoryProject(historyProject||project?.id||'');setTab('audit')}}>بازکردن تاریخچه فعالیت‌ها <ChevronLeft size={16}/></button></div><p className="hint">تغییر تعداد، افزودن و حذف قلم یا ماژول، تغییر قیمت و تغییر وضعیت را با زمان و نام ثبت‌کننده در صفحه تاریخچه فعالیت‌ها ببینید.</p></div>
 <div className="panel"><h3>ذخیره‌سازی آزمایشی</h3><p className="hint">اطلاعات در LocalStorage مرورگر هستند و ممیزی رسمی محسوب نمی‌شوند. برای تهیه نسخه پشتیبان خروجی JSON بگیرید.</p><div className="actions"><button className="btn ghost" onClick={downloadJson}><FileJson size={16}/> ذخیره پشتیبان JSON</button><button className="btn danger-btn" onClick={reset}><RotateCcw size={16}/> بازگردانی داده نمونه</button></div></div>
 </>}
 </main><footer>Engineering BOM App • Prototype v0.4 • داده‌های آزمایشی و قیمت‌های فرضی</footer></div></div>
}
function AddLineForm({items,assemblies,projects,addLine,canEditReadonly}){
 const types={item:'قلم',module:'ماژول',system:'سامانه',project:'پروژه'};
 const allowed={module:['item','module'],system:['item','module','system'],project:['item','module','system','project']};
 const [structureType,setStructureType]=useState('module');
 const [structureId,setStructureId]=useState('');
 const [structureQuery,setStructureQuery]=useState('');
 const [structureOpen,setStructureOpen]=useState(false);
 const [type,setType]=useState('item');
 const [ref,setRef]=useState('');
 const [query,setQuery]=useState('');
 const [pickerOpen,setPickerOpen]=useState(false);
 const structures=[...assemblies,...projects].filter(a=>a.type===structureType);
 const chosenStructure=structures.find(a=>a.id===structureId);
 const validTypes=allowed[structureType]||[];
 const currentType=validTypes.includes(type)?type:(validTypes[0]||'item');
 const candidates=currentType==='item'?items:currentType==='project'?projects:assemblies.filter(a=>a.type===currentType);
 const options=candidates.filter(a=>a.id!==structureId&&clean(a.id+' '+a.name+' '+(a.mpn||'')).includes(clean(query)));
 const structureOptions=structures.filter(a=>clean(a.id+' '+a.name).includes(clean(structureQuery)));
 const selected=candidates.find(x=>x.id===ref);
 const chooseStructure=a=>{setStructureId(a.id);setStructureQuery(a.name);setStructureOpen(false);setRef('');setQuery('');setPickerOpen(false)};
 const choosePart=a=>{setRef(a.id);setQuery(a.name);setPickerOpen(false)};
 return <div className="panel"><h3>افزودن به ساختار BOM</h3>
 <form className="formgrid" onSubmit={e=>{e.preventDefault();if(!chosenStructure||!ref||!candidates.some(x=>x.id===ref)||!canEditReadonly(structureId))return;addLine(e);setRef('');setQuery('');setPickerOpen(false)}}>
 <label>نوع ساختار<select value={structureType} onChange={e=>{setStructureType(e.target.value);setStructureId('');setStructureQuery('');setStructureOpen(false);setType('item');setRef('');setQuery('');setPickerOpen(false)}}><option value="module">ماژول</option><option value="system">سامانه</option><option value="project">پروژه</option></select></label>
 <input type="hidden" name="target" value={structureId}/>
 <div className="child-picker"><label htmlFor="structure-search">انتخاب ساختار</label><div className="child-picker-control"><input id="structure-search" autoComplete="off" value={structureQuery} onFocus={()=>setStructureOpen(true)} onChange={e=>{setStructureQuery(e.target.value);setStructureId('');setStructureOpen(true);setRef('');setQuery('');setPickerOpen(false)}} onKeyDown={e=>{if(e.key==='Escape')setStructureOpen(false);if(e.key==='Enter'&&structureOpen&&structureOptions.length){e.preventDefault();chooseStructure(structureOptions[0])}}} placeholder="جستجو بر اساس نام یا شناسه"/><button type="button" className="child-picker-toggle" aria-label={structureOpen?'بستن فهرست':'نمایش ساختارها'} onClick={()=>{setStructureOpen(v=>!v);setPickerOpen(false)}}>{structureOpen?'▲':'▼'}</button></div>{structureOpen&&<><button type="button" className="child-picker-backdrop" aria-label="بستن فهرست ساختارها" onClick={()=>setStructureOpen(false)}/><div className="child-results" role="listbox">{structureOptions.slice(0,12).map(a=><button type="button" role="option" aria-selected={structureId===a.id} disabled={!canEditReadonly(a.id)} key={a.id} className={'child-option '+(structureId===a.id?'picked':'')} onClick={()=>chooseStructure(a)}><span>{a.name}</span><small dir="ltr">{a.id}</small></button>)}{!structureOptions.length&&<div className="empty">ساختاری یافت نشد.</div>}</div></>}</div>
 <label>نوع جزء<select value={currentType} onChange={e=>{setType(e.target.value);setRef('');setQuery('');setPickerOpen(false)}}>{Object.entries(types).filter(([id])=>validTypes.includes(id)).map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label>
 <input type="hidden" name="kind" value={currentType==='item'?'item':'assembly'}/><input type="hidden" name="ref" value={ref}/>
 <div className="child-picker"><label htmlFor="child-search">انتخاب جزء</label><div className="child-picker-control"><input id="child-search" autoComplete="off" value={query} onFocus={()=>{setPickerOpen(true);setStructureOpen(false)}} onChange={e=>{setQuery(e.target.value);setRef('');setPickerOpen(true);setStructureOpen(false)}} onKeyDown={e=>{if(e.key==='Escape')setPickerOpen(false);if(e.key==='Enter'&&pickerOpen&&options.length){e.preventDefault();choosePart(options[0])}}} placeholder="جستجو بر اساس نام، شناسه یا MPN"/><button type="button" className="child-picker-toggle" aria-label={pickerOpen?'بستن فهرست':'نمایش اجزا'} onClick={()=>{setPickerOpen(v=>!v);setStructureOpen(false)}}>{pickerOpen?'▲':'▼'}</button></div>{pickerOpen&&<><button type="button" className="child-picker-backdrop" aria-label="بستن فهرست اجزا" onClick={()=>setPickerOpen(false)}/><div className="child-results" role="listbox">{options.slice(0,12).map(a=><button type="button" role="option" aria-selected={ref===a.id} key={a.id} className={'child-option '+(ref===a.id?'picked':'')} onClick={()=>choosePart(a)}><span>{a.name}</span><small dir="ltr">{a.id} {a.mpn||''}</small></button>)}{!options.length&&<div className="empty">موردی پیدا نشد.</div>}</div></>}{selected&&<small className="selected-child">✓ {selected.name} ({selected.id})</small>}</div>
 <label>تعداد<input name="qty" type="number" step="0.001" min="0.001" defaultValue="1" required/></label>
 {currentType!=='item'&&<label>نوع استفاده<select name="mode"><option value="reference">Reference</option><option value="duplicate">Duplicate</option></select></label>}
 <button className="btn primary" disabled={!structureId||!ref||!canEditReadonly(structureId)}><Plus size={16}/> افزودن به BOM</button>
 </form></div>
}

createRoot(document.getElementById('root')).render(<App/>);
